insert into public.plants (
  id,
  image_key,
  name,
  short_description,
  description,
  watering_interval_days,
  watering_text,
  light_type,
  light_text,
  repotting_interval_months,
  repotting_text,
  is_toxic,
  toxicity_text,
  difficulty,
  size,
  decorative_level,
  is_pet_friendly,
  temperature_preferred,
  temperature_tolerated
) values
('monstera', 'monstera', 'Монстера', 'Крупное декоративное растение с резными листьями.', 'Монстера любит стабильный уход, рассеянный свет и умеренный полив после подсыхания верхнего слоя почвы.', 7, 'Поливайте примерно раз в неделю, когда верхний слой почвы подсох.', 'bright_indirect', 'Лучше всего подходит яркий рассеянный свет без прямого полуденного солнца.', 12, 'Молодые растения пересаживают примерно раз в год, взрослые - реже.', true, 'Может быть токсична для кошек, собак и маленьких детей.', 'medium', 'large', 3, false, 'medium', array['medium','high']),
('sansevieria', 'sansevieria', 'Сансевиерия', 'Неприхотливое растение с плотными вертикальными листьями.', 'Сансевиерия хорошо переносит редкий полив и подходит новичкам.', 14, 'Поливайте редко, после полного подсыхания почвы.', 'partial_shade', 'Подходит яркий рассеянный свет и полутень.', 24, 'Пересадка нужна редко, когда корням становится тесно.', true, 'Может быть токсична для домашних животных.', 'easy', 'medium', 2, false, 'medium', array['medium','high']),
('ficus-benjamina', 'ficus', 'Фикус Бенджамина', 'Изящное комнатное деревце с мелкими листьями.', 'Фикус Бенджамина любит постоянное место, рассеянный свет и аккуратный полив.', 7, 'Поливайте умеренно, не допускайте заболачивания.', 'bright_indirect', 'Нужен яркий рассеянный свет.', 12, 'Пересаживайте примерно раз в год или по мере роста.', true, 'Сок растения может раздражать кожу и быть опасен для животных.', 'medium', 'large', 3, false, 'medium', array['medium']),
('spathiphyllum', 'spaifillium', 'Спатифиллум', 'Цветущее растение с белыми покрывалами и глянцевыми листьями.', 'Спатифиллум любит влажную почву без застоя воды и мягкое освещение.', 5, 'Поливайте, когда верхний слой почвы начал подсыхать.', 'partial_shade', 'Хорошо растёт в полутени и рассеянном свете.', 12, 'Пересаживайте весной примерно раз в год.', true, 'Может быть токсичен для кошек, собак и детей.', 'medium', 'medium', 3, false, 'medium', array['medium','high']),
('zamioculcas', 'zamiokulkas', 'Замиокулькас', 'Выносливое растение с плотными блестящими листьями.', 'Замиокулькас хорошо переносит редкий полив и подходит занятым людям.', 14, 'Поливайте редко, когда грунт хорошо просох.', 'partial_shade', 'Подходит рассеянный свет и полутень.', 24, 'Пересадка нужна редко, когда клубням становится тесно.', true, 'Может быть токсичен для домашних животных.', 'easy', 'medium', 2, false, 'medium', array['medium','high']),
('chlorophytum', 'chlorofitum', 'Хлорофитум', 'Неприхотливое растение с дуговидными листьями и детками.', 'Хлорофитум быстро растёт, легко размножается и прощает небольшие ошибки ухода.', 6, 'Поливайте умеренно, не пересушивая надолго.', 'partial_shade', 'Подходит рассеянный свет и полутень.', 12, 'Пересаживайте по мере заполнения горшка корнями.', false, 'Обычно считается безопасным для домашних животных.', 'easy', 'medium', 2, true, 'medium', array['low','medium','high']),
('cactus', 'cactus', 'Кактус', 'Компактное растение для солнечных мест.', 'Кактусы любят много света, сухой грунт и очень осторожный полив.', 21, 'Поливайте редко, только после полного высыхания грунта.', 'bright_indirect', 'Нужен очень светлый подоконник.', 24, 'Пересаживайте редко, когда горшок стал мал.', false, 'Обычно безопасен, но колючки могут травмировать.', 'easy', 'small', 2, true, 'high', array['medium','high']),
('phalaenopsis', 'orchidea', 'Орхидея фаленопсис', 'Декоративная орхидея с долгим цветением.', 'Фаленопсис требует аккуратного полива, прозрачного горшка и рассеянного света.', 7, 'Поливайте после подсыхания корней и субстрата.', 'bright_indirect', 'Нужен яркий рассеянный свет без прямого солнца.', 24, 'Пересаживайте после разложения коры или раз в 1-2 года.', false, 'Обычно считается безопасной для домашних животных.', 'hard', 'medium', 3, true, 'medium', array['medium','high']),
('peperomia', 'peperomia', 'Пеперомия', 'Небольшое декоративное растение с плотными листьями.', 'Пеперомия любит умеренный полив, лёгкий грунт и рассеянный свет.', 10, 'Поливайте после подсыхания верхней части грунта.', 'partial_shade', 'Подходит рассеянный свет и лёгкая полутень.', 12, 'Пересаживайте по мере необходимости, обычно раз в 1-2 года.', false, 'Обычно считается безопасной для домашних животных.', 'easy', 'small', 2, true, 'medium', array['medium','high']),
('dracaena', 'dracena', 'Драцена', 'Вертикальное декоративное растение для интерьера.', 'Драцена любит рассеянный свет, умеренный полив и не любит перелив.', 10, 'Поливайте после подсыхания верхнего слоя почвы.', 'partial_shade', 'Лучше всего подходит рассеянный свет или полутень.', 18, 'Пересаживайте по мере роста корней.', true, 'Может быть токсична для кошек и собак.', 'medium', 'large', 2, false, 'medium', array['medium','high']),
('aloe-vera', 'aloe', 'Алоэ вера', 'Суккулент с мясистыми листьями, который любит свет.', 'Алоэ вера предпочитает яркое место и редкий полив.', 14, 'Поливайте редко, когда грунт полностью просох.', 'bright_indirect', 'Нужно светлое место, можно с мягким солнцем.', 24, 'Пересаживайте редко, когда растению тесно.', true, 'Может быть токсично для животных при поедании.', 'easy', 'small', 2, false, 'high', array['medium','high']),
('anthurium', 'anturium', 'Антуриум', 'Яркое цветущее растение с глянцевыми листьями.', 'Антуриум любит тёплые условия, влажный воздух и аккуратный полив.', 6, 'Поливайте умеренно, не допуская застоя воды.', 'bright_indirect', 'Нужен яркий рассеянный свет.', 12, 'Пересаживайте раз в год или при уплотнении грунта.', true, 'Может быть токсичен для детей и домашних животных.', 'hard', 'medium', 3, false, 'medium', array['medium','high'])
on conflict (id) do update set
  image_key = excluded.image_key,
  name = excluded.name,
  short_description = excluded.short_description,
  description = excluded.description,
  watering_interval_days = excluded.watering_interval_days,
  watering_text = excluded.watering_text,
  light_type = excluded.light_type,
  light_text = excluded.light_text,
  repotting_interval_months = excluded.repotting_interval_months,
  repotting_text = excluded.repotting_text,
  is_toxic = excluded.is_toxic,
  toxicity_text = excluded.toxicity_text,
  difficulty = excluded.difficulty,
  size = excluded.size,
  decorative_level = excluded.decorative_level,
  is_pet_friendly = excluded.is_pet_friendly,
  temperature_preferred = excluded.temperature_preferred,
  temperature_tolerated = excluded.temperature_tolerated;
